// When sets expectation for the ClassService.UpdateClass which will trigger the result defined by the following
// Then helper
func (mmUpdateClass *mClassServiceMockUpdateClass) When(ctx context.Context, id int64, updates map[string]any) *ClassServiceMockUpdateClassExpectation {
	if mmUpdateClass.mock.funcUpdateClass != nil {
		mmUpdateClass.mock.t.Fatalf("ClassServiceMock.UpdateClass mock is already set by Set")
	}

	expectation := &ClassServiceMockUpdateClassExpectation{
		mock:               mmUpdateClass.mock,
		params:             &ClassServiceMockUpdateClassParams{ctx, id, updates},
		expectationOrigins: ClassServiceMockUpdateClassExpectationOrigins{origin: minimock.CallerInfo(1)},
	}
	mmUpdateClass.expectations = append(mmUpdateClass.expectations, expectation)
	return expectation
}

// Then sets up ClassService.UpdateClass return parameters for the expectation previously defined by the When method
func (e *ClassServiceMockUpdateClassExpectation) Then(cp1 *entities.Class, err error) *ClassServiceMock {
	e.results = &ClassServiceMockUpdateClassResults{cp1, err}
	return e.mock
}

// Times sets number of times ClassService.UpdateClass should be invoked
func (mmUpdateClass *mClassServiceMockUpdateClass) Times(n uint64) *mClassServiceMockUpdateClass {
	if n == 0 {
		mmUpdateClass.mock.t.Fatalf("Times of ClassServiceMock.UpdateClass mock can not be zero")
	}
	mm_atomic.StoreUint64(&mmUpdateClass.expectedInvocations, n)
	mmUpdateClass.expectedInvocationsOrigin = minimock.CallerInfo(1)
	return mmUpdateClass
}

func (mmUpdateClass *mClassServiceMockUpdateClass) invocationsDone() bool {
	if len(mmUpdateClass.expectations) == 0 && mmUpdateClass.defaultExpectation == nil && mmUpdateClass.mock.funcUpdateClass == nil {
		return true
	}

	totalInvocations := mm_atomic.LoadUint64(&mmUpdateClass.mock.afterUpdateClassCounter)
	expectedInvocations := mm_atomic.LoadUint64(&mmUpdateClass.expectedInvocations)

	return totalInvocations > 0 && (expectedInvocations == 0 || expectedInvocations == totalInvocations)
}

// UpdateClass implements mm_handlers.ClassService
func (mmUpdateClass *ClassServiceMock) UpdateClass(ctx context.Context, id int64, updates map[string]any) (cp1 *entities.Class, err error) {
	mm_atomic.AddUint64(&mmUpdateClass.beforeUpdateClassCounter, 1)
	defer mm_atomic.AddUint64(&mmUpdateClass.afterUpdateClassCounter, 1)

	mmUpdateClass.t.Helper()

	if mmUpdateClass.inspectFuncUpdateClass != nil {
		mmUpdateClass.inspectFuncUpdateClass(ctx, id, updates)
	}

	mm_params := ClassServiceMockUpdateClassParams{ctx, id, updates}

	// Record call args
	mmUpdateClass.UpdateClassMock.mutex.Lock()
	mmUpdateClass.UpdateClassMock.callArgs = append(mmUpdateClass.UpdateClassMock.callArgs, &mm_params)
	mmUpdateClass.UpdateClassMock.mutex.Unlock()

	for _, e := range mmUpdateClass.UpdateClassMock.expectations {
		if minimock.Equal(*e.params, mm_params) {
			mm_atomic.AddUint64(&e.Counter, 1)
			return e.results.cp1, e.results.err
		}
	}

	if mmUpdateClass.UpdateClassMock.defaultExpectation != nil {
		mm_atomic.AddUint64(&mmUpdateClass.UpdateClassMock.defaultExpectation.Counter, 1)
		mm_want := mmUpdateClass.UpdateClassMock.defaultExpectation.params
		mm_want_ptrs := mmUpdateClass.UpdateClassMock.defaultExpectation.paramPtrs

		mm_got := ClassServiceMockUpdateClassParams{ctx, id, updates}

		if mm_want_ptrs != nil {

			if mm_want_ptrs.ctx != nil && !minimock.Equal(*mm_want_ptrs.ctx, mm_got.ctx) {
				mmUpdateClass.t.Errorf("ClassServiceMock.UpdateClass got unexpected parameter ctx, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
					mmUpdateClass.UpdateClassMock.defaultExpectation.expectationOrigins.originCtx, *mm_want_ptrs.ctx, mm_got.ctx, minimock.Diff(*mm_want_ptrs.ctx, mm_got.ctx))
			}

			if mm_want_ptrs.id != nil && !minimock.Equal(*mm_want_ptrs.id, mm_got.id) {
				mmUpdateClass.t.Errorf("ClassServiceMock.UpdateClass got unexpected parameter id, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
					mmUpdateClass.UpdateClassMock.defaultExpectation.expectationOrigins.originId, *mm_want_ptrs.id, mm_got.id, minimock.Diff(*mm_want_ptrs.id, mm_got.id))
			}

			if mm_want_ptrs.updates != nil && !minimock.Equal(*mm_want_ptrs.updates, mm_got.updates) {
				mmUpdateClass.t.Errorf("ClassServiceMock.UpdateClass got unexpected parameter updates, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
					mmUpdateClass.UpdateClassMock.defaultExpectation.expectationOrigins.originUpdates, *mm_want_ptrs.updates, mm_got.updates, minimock.Diff(*mm_want_ptrs.updates, mm_got.updates))
			}

		} else if mm_want != nil && !minimock.Equal(*mm_want, mm_got) {
			mmUpdateClass.t.Errorf("ClassServiceMock.UpdateClass got unexpected parameters, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
				mmUpdateClass.UpdateClassMock.defaultExpectation.expectationOrigins.origin, *mm_want, mm_got, minimock.Diff(*mm_want, mm_got))
		}

		mm_results := mmUpdateClass.UpdateClassMock.defaultExpectation.results
		if mm_results == nil {
			mmUpdateClass.t.Fatal("No results are set for the ClassServiceMock.UpdateClass")
		}
		return (*mm_results).cp1, (*mm_results).err
	}
	if mmUpdateClass.funcUpdateClass != nil {
		return mmUpdateClass.funcUpdateClass(ctx, id, updates)
	}
	mmUpdateClass.t.Fatalf("Unexpected call to ClassServiceMock.UpdateClass. %v %v %v", ctx, id, updates)
	return
}

// UpdateClassAfterCounter returns a count of finished ClassServiceMock.UpdateClass invocations
func (mmUpdateClass *ClassServiceMock) UpdateClassAfterCounter() uint64 {
	return mm_atomic.LoadUint64(&mmUpdateClass.afterUpdateClassCounter)
}

// UpdateClassBeforeCounter returns a count of ClassServiceMock.UpdateClass invocations
func (mmUpdateClass *ClassServiceMock) UpdateClassBeforeCounter() uint64 {
	return mm_atomic.LoadUint64(&mmUpdateClass.beforeUpdateClassCounter)
}

// Calls returns a list of arguments used in each call to ClassServiceMock.UpdateClass.
// The list is in the same order as the calls were made (i.e. recent calls have a higher index)
func (mmUpdateClass *mClassServiceMockUpdateClass) Calls() []*ClassServiceMockUpdateClassParams {
	mmUpdateClass.mutex.RLock()

	argCopy := make([]*ClassServiceMockUpdateClassParams, len(mmUpdateClass.callArgs))
	copy(argCopy, mmUpdateClass.callArgs)

	mmUpdateClass.mutex.RUnlock()

	return argCopy
}

// MinimockUpdateClassDone returns true if the count of the UpdateClass invocations corresponds
// the number of defined expectations
func (m *ClassServiceMock) MinimockUpdateClassDone() bool {
	if m.UpdateClassMock.optional {
		// Optional methods provide '0 or more' call count restriction.
		return true
	}

	for _, e := range m.UpdateClassMock.expectations {
		if mm_atomic.LoadUint64(&e.Counter) < 1 {
			return false
		}
	}

	return m.UpdateClassMock.invocationsDone()
}

// MinimockUpdateClassInspect logs each unmet expectation
func (m *ClassServiceMock) MinimockUpdateClassInspect() {
	for _, e := range m.UpdateClassMock.expectations {
		if mm_atomic.LoadUint64(&e.Counter) < 1 {
			m.t.Errorf("Expected call to ClassServiceMock.UpdateClass at\n%s with params: %#v", e.expectationOrigins.origin, *e.params)
		}
	}

	afterUpdateClassCounter := mm_atomic.LoadUint64(&m.afterUpdateClassCounter)
	// if default expectation was set then invocations count should be greater than zero
	if m.UpdateClassMock.defaultExpectation != nil && afterUpdateClassCounter < 1 {
		if m.UpdateClassMock.defaultExpectation.params == nil {
			m.t.Errorf("Expected call to ClassServiceMock.UpdateClass at\n%s", m.UpdateClassMock.defaultExpectation.returnOrigin)
		} else {
			m.t.Errorf("Expected call to ClassServiceMock.UpdateClass at\n%s with params: %#v", m.UpdateClassMock.defaultExpectation.expectationOrigins.origin, *m.UpdateClassMock.defaultExpectation.params)
		}
	}
	// if func was set then invocations count should be greater than zero
	if m.funcUpdateClass != nil && afterUpdateClassCounter < 1 {
		m.t.Errorf("Expected call to ClassServiceMock.UpdateClass at\n%s", m.funcUpdateClassOrigin)
	}

	if !m.UpdateClassMock.invocationsDone() && afterUpdateClassCounter > 0 {
		m.t.Errorf("Expected %d calls to ClassServiceMock.UpdateClass at\n%s but found %d calls",
			mm_atomic.LoadUint64(&m.UpdateClassMock.expectedInvocations), m.UpdateClassMock.expectedInvocationsOrigin, afterUpdateClassCounter)
	}
}

// MinimockFinish checks that all mocked methods have been called the expected number of times
func (m *ClassServiceMock) MinimockFinish() {
	m.finishOnce.Do(func() {
		if !m.minimockDone() {
			m.MinimockCreateClassInspect()

			m.MinimockDeleteClassByIDInspect()

			m.MinimockGetAllClassesInspect()

			m.MinimockGetChildClassesInspect()

			m.MinimockGetClassByIDInspect()

			m.MinimockGetParentClassInspect()

			m.MinimockUpdateClassInspect()
		}
	})
}

// MinimockWait waits for all mocked methods to be called the expected number of times
func (m *ClassServiceMock) MinimockWait(timeout mm_time.Duration) {
	timeoutCh := mm_time.After(timeout)
	for {
		if m.minimockDone() {
			return
		}
		select {
		case <-timeoutCh:
			m.MinimockFinish()
			return
		case <-mm_time.After(10 * mm_time.Millisecond):
		}
	}
}

func (m *ClassServiceMock) minimockDone() bool {
	done := true
	return done &&
		m.MinimockCreateClassDone() &&
		m.MinimockDeleteClassByIDDone() &&
		m.MinimockGetAllClassesDone() &&
		m.MinimockGetChildClassesDone() &&
		m.MinimockGetClassByIDDone() &&
		m.MinimockGetParentClassDone() &&
		m.MinimockUpdateClassDone()
}
